// Ambient type declarations for desktop/plugin.js.
//
// Cheat-sheet for the plugin author:
//   - `// @ts-check` is enabled per-file in plugin.js.
//   - Pull a shape in via JSDoc: `/** @type {import('./types.d.ts').Palette} */`.
//   - Or alias once at the top of plugin.js:
//        /** @typedef {import('./types.d.ts').Palette} Palette */
//     and reference it by short name in every later annotation.
//   - The plugin does NOT consume this file at runtime — `npx tsc --allowJs
//     --checkJs --noEmit` reads it only for type-checking; nothing is emitted.
//   - Keep this file in sync with the contracts below. Numeric/string
//     defaults are documented alongside each field; the smoke test
//     (tests/smoke.mjs) is the executable spec for the shapes plugin.js
//     builds — when an assertion there is loosened, mirror it here.

// ─── Raw Omarchy palette (parsed from colors.toml) ──────────────────────────
// Every key is optional: tokens missing in a theme's colors.toml fall back
// to a synthesised value in paletteFromToml() or to a DEFAULT inside the
// helpers that consume them (buildTheme / nativePalette / terminalPalette).
// The three anchor fields (background/foreground/accent) are required at the
// type level because downstream helpers (mixHex, theme-builder) cannot
// tolerate `undefined` here — buildTheme's null-return guard is the loader.
export interface Palette {
  /** 'light' | 'dark' — Omarchy's own mode token; falls back to luma(). */
  mode?: 'light' | 'dark' | string
  /** Foreground/accent/background — the theme's three anchor colours.
   *  Required: every consumer assumes these are present (buildTheme
   *  returns null when any of them are missing, see plugin.js). */
  accent: string
  background: string
  foreground: string
  /** Selection highlighter colour (may use the underscored alias from
   *  some Omarchy palette authors). */
  selection?: string
  selection_background?: string
  /** Muted surfaces for popovers / chips. */
  muted?: string
  /** Foreground-toned helpers used by the dark variant. */
  dark_foreground?: string
  dark_background?: string
  darker_background?: string
  lighter_background?: string
  /** Bright variants (typically the same hex as foreground, sometimes
   *  bumped to pure white). */
  bright_foreground?: string
  /** ANSI colours as Omarchy ships them. */
  red?: string
  green?: string
  yellow?: string
  blue?: string
  magenta?: string
  cyan?: string
  bright_red?: string
  bright_green?: string
  bright_yellow?: string
  bright_blue?: string
  bright_magenta?: string
  bright_cyan?: string
}

// ─── Building blocks ────────────────────────────────────────────────────────
/** 'light' | 'dark' — Hermes Desktop's two render modes. */
export type Mode = 'light' | 'dark'

/** One half of a DesktopTheme (Light `colors` OR Dark `darkColors`). All
 *  keys are required — buildTheme() always emits both halves. */
export interface ColorScale {
  background: string
  foreground: string
  card: string
  cardForeground: string
  popover: string
  popoverForeground: string
  primary: string
  primaryForeground: string
  secondary: string
  secondaryForeground: string
  accent: string
  accentForeground: string
  muted: string
  mutedForeground: string
  border: string
  input: string
  ring: string
  midground: string
  composerRing: string
  destructive: string
  destructiveForeground: string
  sidebarBackground: string
  sidebarBorder: string
  userBubble: string
  userBubbleBorder: string
}

/** One terminal palette (Light `terminal` OR Dark `darkTerminal`). */
export interface TerminalPalette {
  foreground: string
  cursor: string
  selectionBackground: string
  black: string
  red: string
  green: string
  yellow: string
  blue: string
  magenta: string
  cyan: string
  white: string
  brightBlack: string
  brightRed: string
  brightGreen: string
  brightYellow: string
  brightBlue: string
  brightMagenta: string
  brightCyan: string
  brightWhite: string
}

/** Font stacks — matches Hermes Desktop's bundled presets so the OS font and
 *  emoji rendering stay intact. */
export interface Typography {
  fontSans: string
  fontMono: string
}

/** The full theme contribution (one entry per registered theme). */
export interface DesktopTheme {
  name: string
  label: string
  description: string
  colors: ColorScale
  darkColors: ColorScale
  terminal: TerminalPalette
  darkTerminal: TerminalPalette
  typography: Typography
}

/** What buildTheme() returns and what THEMES.flatMap produces; registered
 *  with the host as `data` via ctx.register({ area: THEMES_AREA, ... }). */
export interface ThemeEntry {
  slug: string
  label: string
  mode: Mode
  theme: DesktopTheme
}

/** One row of the baked RAW table (generated by scripts/generate-themes.py
 *  — do not edit by hand). */
export interface RawEntry {
  slug: string
  c: Palette
}

// ─── Bridges the host exposes on `window.hermesDesktop` ────────────────────
// Only the methods this plugin uses are typed; the real bridge exposes
// many more, all declared `any` here.
export interface HermesBridge {
  desktopPluginsRoot(): Promise<string> | string
  getMachineProfile?(): Promise<{ username?: string }> | { username?: string }
  readFileText(path: string): Promise<{ text?: string }> | { text?: string }
  watchPreviewFile(path: string): Promise<{ id: string }> | { id: string }
  stopPreviewFileWatch?(id: string): void
  onPreviewFileChanged(handler: (payload: { id: string } | null) => void): () => void
}

/** Persisted plugin-scoped key/value store (often backed by localStorage on
 *  the renderer side). Missing keys fall back to `fallback`. */
export interface PluginStorage {
  get<T = unknown>(key: string, fallback: T): T
  set(key: string, value: unknown): void
}

/** What `register(ctx)` receives. Mirrors @hermes/plugin-sdk's contract; the
 *  ctx.storage and ctx.registerSettingsPage hooks are optional in this
 *  plugin's usage. */
export interface PluginContext {
  register(contribution: {
    id: string
    area: string
    data?: unknown
  }): () => void
  registerSettingsPage?(page: SettingsPage): void
  onEvent(type: string, listener: (event: { type: string; payload?: any }) => void): () => void
  onDispose(fn: () => void): void
  storage?: PluginStorage
  /** Clipboard helper exposed by the desktop host — `writeClipboard(text)`
   *  is invoked by the Copy-name button in the settings page. */
  os?: { writeClipboard(text: string): boolean | void }
}

/** What registerSettingsPage() expects. */
export interface SettingsPage {
  id: string
  title: string
  icon?: string
  order?: number
  render: () => unknown
  children?: SettingsPage[]
}

// ─── @hermes/plugin-sdk namespace (only the exports plugin.js uses) ──────
export interface ThemeModeContext {
  setMode: (mode: Mode) => void
}

/** The subset of @hermes/plugin-sdk this plugin imports. requestMode is
 *  optional — today the SDK does not re-export it (probed at module load);
 *  when it lands, plugin.js delegates to SDK_REQUEST_MODE. */
export interface PluginSdk {
  THEMES_AREA: string
  PALETTE_AREA: string
  requestTheme(name: string): boolean | void
  requestMode?(mode: Mode): void
  useTheme(): ThemeModeContext
  Button: unknown
  EmptyState: unknown
}

// ─── JSX runtime (react/jsx-runtime) ───────────────────────────────────────
export interface JsxRuntime {
  jsx(type: unknown, props: Record<string, unknown>, key?: unknown): unknown
  jsxs(type: unknown, props: Record<string, unknown>, key?: unknown): unknown
}

// ─── Helpers ───────────────────────────────────────────────────────────────
/** A #rrggbb colour (lowercase, leading '#'). Typed as plain string so
 *  callers can pass `c.background` (Palette.background is `string`) without
 *  fighting the strict template-literal type; the runtime invariant is
 *  documented in JSDoc and enforced by tests/smoke.mjs (HEX regex). */
export type Hex = string

/** Function that returns true while the current instance is the live one.
 *  Used as the `alive` parameter on long async operations; a disposed
 *  instance checks before touching shared module state. */
export type AliveCheck = () => boolean

/** Result of registerCurrent(): 'new' when the dynamic theme changed,
 *  'same' when it already matches, null when colors.toml gave no palette. */
export type RegisterCurrentResult = 'new' | 'same' | null

// ─── Helpers ───────────────────────────────────────────────────────────────
/** A #rrggbb colour (lowercase, leading '#'). Typed as plain string so
 *  callers can pass `c.background` (Palette.background is `string`) without
 *  fighting the strict template-literal type; the runtime invariant is
 *  documented in JSDoc and enforced by tests/smoke.mjs (HEX regex). */
export type Hex = string
